Lemma fsz_0 : fsz 0 = 64.     Proof. reflexivity. Qed.
Lemma fsz_2 : fsz 2 = 256.    Proof. reflexivity. Qed.
Lemma fsz_3 : fsz 3 = 512.    Proof. reflexivity. Qed.
Lemma fsz_7 : fsz 7 = 8192.   Proof. reflexivity. Qed.
Lemma fshn_0 : fshn 0 = 8.    Proof. reflexivity. Qed.
Lemma fshn_2 : fshn 2 = 32.   Proof. reflexivity. Qed.
Lemma fshn_3 : fshn 3 = 64.   Proof. reflexivity. Qed.
Lemma fshn_7 : fshn 7 = 1024. Proof. reflexivity. Qed.
(* [comment removed for export] *)
Ltac fs_nums_in H := rewrite ?fsz_0, ?fsz_1, ?fsz_2, ?fsz_3, ?fsz_4, ?fsz_7, ?fshn_0, ?fshn_1, ?fshn_2, ?fshn_3, ?fshn_4, ?fshn_7 in H.
Ltac fs_nums := rewrite ?fsz_0, ?fsz_1, ?fsz_2, ?fsz_3, ?fsz_4, ?fsz_7, ?fshn_0, ?fshn_1, ?fshn_2, ?fshn_3, ?fshn_4, ?fshn_7.

Lemma fshn_8 : forall k, 0 <= k -> 8 * fshn k = fsz k.
Proof. intros k Hk. unfold fshn, fsz. lia. Qed.

