(* [comment removed for export] *)
(* [comment removed for export] *)

Section SIDE.
  Context {HCEIL : HeapCeil}.

  Definition aside (m : mem) (lo shi : Z) (ACC SHV : list (Z * Z)) : Prop :=
    ACONST m /\ stack0 m lo shi
    /\ Forall (fun o : Z * Z => accessible m (fst o) (snd o)) ACC
    /\ Forall (fun o : Z * Z => 0 <= fst o /\ 0 <= snd o /\ fst o + snd o <= AAPP_HI /\ shvis m (fst o) (fst o + snd o)) SHV.

  (* [comment removed for export] *)
  Definition awin (iv : Z * Z) : Prop := aconst_ok iv /\ stack0_ok iv /\ (snd iv <= ALOWSH_LO \/ AHI_LO <= fst iv).

  Lemma awin_stack : forall l h, aceil <= l -> awin (l, h).
  Proof.
    intros l h Hl. pose proof aceil_facts as (AF & _). split; [apply aconst_ok_hi| split; [apply stack0_ok_app| right]]; cbn [fst snd]; unfold AHI_LO; lia.
  Qed.
  Lemma awin_aapp : forall A n l h, aapp A n -> A <= l -> h <= A + n -> awin (l, h).
  Proof.
    intros A n l h AP Hl Hh. split; [eapply aconst_ok_aapp; eauto| split; [eapply stack0_ok_aapp; eauto|]].
    pose proof (aapp_not_shadowland _ _ AP). cbn [fst snd]. lia.
  Qed.
  (* [comment removed for export] *)
  Lemma awin_img : forall l h, aconst_ok (l, h) -> h <= AIMG_TOP -> awin (l, h).
  Proof.
    intros l h AC Hh. pose proof aceil_facts as (AF & _). split; [exact AC| split; [right; cbn [fst snd]| left; cbn [fst snd]]].
    - assert (K1 : AIMG_TOP <= aceil) by (unfold AIMG_TOP; lia). pose proof (sh_mono AIMG_TOP aceil K1).
      pose proof (sh_above_image AIMG_TOP ltac:(unfold AIMG_TOP; lia)). lia.
    - unfold AIMG_TOP, ALOWSH_LO in *. lia.
  Qed.

  Lemma awin_outside_sh : forall W x, Forall awin W -> 0 <= x < AAPP_HI -> outside W (sh x).
  Proof.
    induction W as [|[l h] W IH]; intros x FW Hx; cbn; [exact I|].
    pose proof (Forall_inv FW) as (_ & _ & K). cbn in K.
    pose proof (sh_below_app x Hx). assert (ALOWSH_LO < sh x) by (unfold sh, ALOWSH_LO; rewrite ASHADOW_BASE_val; lia).
    split; [lia| apply IH; [exact (Forall_inv_tail FW)| exact Hx]].
  Qed.
  Lemma awin_disjoint_shland : forall W a n, Forall awin W -> ALOWSH_LO <= a -> a + n <= AHI_LO -> disjoint_from W a n.
  Proof.
    induction W as [|[l h] W IH]; intros a n FW Ha Hn; cbn; [exact I|].
    pose proof (Forall_inv FW) as (_ & _ & K). cbn in K. split; [lia| apply IH; [exact (Forall_inv_tail FW)| exact Ha| exact Hn]].
  Qed.

  Lemma aside_transport : forall W m m' lo shi ACC SHV,
