  Lemma awin_fr_client : forall ff k iv, awin iv -> awin_fr ff k iv.  Proof. intros; left; assumption. Qed.
  Lemma awin_fr_shadow : forall ff k l h, Z.shiftr ff 3 + 2147450880 <= l -> h <= Z.shiftr ff 3 + 2147450880 + fshn k -> awin_fr ff k (l, h).
